from pathlib import Path
from reportlab.lib import colors
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, PageBreak

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs'/'Assignment1_Report.pdf'
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='CoverTitle',parent=styles['Title'],fontSize=20,leading=25,alignment=TA_CENTER,spaceAfter=12))
styles.add(ParagraphStyle(name='Small',parent=styles['BodyText'],fontSize=8,leading=10))
story=[]
story += [Paragraph('DBMS Assignment 1',styles['CoverTitle']),Paragraph('ToyDB: PF Buffering, Slotted Pages, and B+ Tree Indexing',ParagraphStyle('Sub',parent=styles['Heading2'],alignment=TA_CENTER)),Spacer(1,8),Paragraph('Implementation and Experimental Report',ParagraphStyle('Sub2',parent=styles['Normal'],alignment=TA_CENTER)),Spacer(1,18)]
story += [Paragraph('1. Overview',styles['Heading1']),Paragraph('This project implements configurable LRU/MRU page buffering in the PF layer, a variable-length slotted-page heap file in the HF layer, and Student roll-number indexing in the AM layer. All experiments use 17,813 non-empty records from the supplied Student dataset.',styles['BodyText']),Spacer(1,8)]
story += [Paragraph('2. PF page buffering',styles['Heading1']),Paragraph('The PF buffer pool supports a configurable frame count, LRU and MRU replacement, dirty-page writeback, and counters for logical and physical I/O, hits, misses, and evictions. The benchmark uses 128 pages, an 8-frame pool, 10,000 operations per workload, and write shares from 0% to 100%.',styles['BodyText']),Spacer(1,6)]
pfdata=[['Policy','Write %','Logical R','Logical W','Physical R','Physical W','Hits'],['LRU','0','10,000','0','9,319','0','681'],['LRU','25','10,000','2,500','9,319','2,354','681'],['LRU','50','10,000','5,000','9,319','4,721','681'],['LRU','75','10,000','7,500','9,319','7,053','681'],['LRU','100','10,000','10,000','9,319','9,319','681'],['MRU','0','10,000','0','9,360','0','640'],['MRU','25','10,000','2,500','9,360','2,439','640'],['MRU','50','10,000','5,000','9,360','4,810','640'],['MRU','75','10,000','7,500','9,360','7,116','640'],['MRU','100','10,000','10,000','9,360','9,360','640']]
t=Table(pfdata,repeatRows=1,colWidths=[18*mm,15*mm,21*mm,21*mm,22*mm,22*mm,15*mm]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#26384A')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.3,colors.grey),('FONTSIZE',(0,0),(-1,-1),7),('ALIGN',(1,1),(-1,-1),'RIGHT'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F1F4F7')])]))
story += [t,Spacer(1,8),Paragraph('For this deterministic random-access workload, LRU produced 41 fewer physical reads than MRU (9,319 versus 9,360). The difference is small and is specific to this access pattern.',styles['BodyText']),Spacer(1,8),Image(str(ROOT/'results'/'pf_io_by_mix.png'),width=165*mm,height=92*mm),PageBreak()]
story += [Paragraph('3. HF slotted-page storage',styles['Heading1']),Paragraph('The HF layer stores variable-length text records in pages with a header and slot directory. Deletion invalidates a slot; compaction before a subsequent insertion reclaims fragmented space while preserving live record RIDs. The benchmark inserted and sequentially scanned all 17,813 records.',styles['BodyText']),Spacer(1,6)]
hfdata=[['Method','Max record length','Pages','Allocated bytes','Utilization'],['Slotted','Variable','1,921','1,959,420','94.00%'],['Static','112 B','1,980','2,019,600','87.10%'],['Static','128 B','2,545','2,595,900','67.76%'],['Static','160 B','2,969','3,028,380','58.08%'],['Static','192 B','3,563','3,634,260','48.40%'],['Static','256 B','5,938','6,056,760','29.04%']]
t=Table(hfdata,repeatRows=1,colWidths=[27*mm,35*mm,22*mm,36*mm,25*mm]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#26384A')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.3,colors.grey),('FONTSIZE',(0,0),(-1,-1),8),('ALIGN',(2,1),(-1,-1),'RIGHT'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F1F4F7')])]))
story += [t,Spacer(1,8),Paragraph('The slotted-page representation uses fewer pages than every tested static record length and reaches approximately 94% utilization. Static allocation becomes less efficient as the maximum record length grows.',styles['BodyText']),Spacer(1,8),Image(str(ROOT/'results'/'hf_space_utilization.png'),width=165*mm,height=92*mm),PageBreak()]
story += [Paragraph('4. AM B+ tree indexing',styles['Heading1']),Paragraph('The second semicolon-separated Student field is an 8-character roll number and is indexed as a fixed-width character key. Duplicate roll numbers are retained using RID overflow chains. The input row number is used as the record identifier.',styles['BodyText']),Spacer(1,6)]
amdata=[['Construction method','Build time (s)','Logical page accesses','Physical reads','Physical writes'],['Existing-file pass','0.021132','50,492','289','748'],['Incremental shuffled','0.053679','50,172','15,156','15,085'],['Bottom-up bulk load','0.001056','289','289','583']]
t=Table(amdata,repeatRows=1,colWidths=[42*mm,25*mm,35*mm,25*mm,28*mm]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#26384A')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.3,colors.grey),('FONTSIZE',(0,0),(-1,-1),7),('ALIGN',(1,1),(-1,-1),'RIGHT'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F1F4F7')])]))
story += [t,Spacer(1,8),Paragraph('The bottom-up loader sorts keys, packs leaf pages including duplicate RID chains, and constructs internal levels from child minimum keys. This avoids repeated tree searches and split operations during construction.',styles['BodyText']),Spacer(1,6)]
qdata=[['Method','100-query time (s)','Logical page accesses','Physical reads','Correct'],['Existing-file pass','0.003398','500','98','100/100'],['Incremental shuffled','0.003757','500','115','100/100'],['Bottom-up bulk load','0.003359','500','41','100/100']]
t=Table(qdata,repeatRows=1,colWidths=[42*mm,30*mm,35*mm,25*mm,23*mm]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#26384A')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.3,colors.grey),('FONTSIZE',(0,0),(-1,-1),7),('ALIGN',(1,1),(-1,-1),'RIGHT'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F1F4F7')])]))
story += [t,Spacer(1,8),Paragraph('All three methods returned the correct record for 100 deterministic equality lookups. The bottom-up index also passed a full sequential scan returning all 17,813 record IDs.',styles['BodyText']),Spacer(1,8),Image(str(ROOT/'results'/'am_build_time.png'),width=165*mm,height=92*mm),Spacer(1,6),Image(str(ROOT/'results'/'am_query_page_accesses.png'),width=165*mm,height=92*mm),PageBreak()]
story += [Paragraph('5. Validation and reproduction',styles['Heading1']),Paragraph('Run <b>make clean && make</b> from the repository root to compile. Run <b>./run_all_experiments.sh</b> to reproduce the PF, HF, and AM measurements and regenerate the CSV files and figures. The HF test program checks insertion, retrieval, deletion, deleted-slot rejection, slot reuse after compaction, and sequential scanning.',styles['BodyText']),Spacer(1,8),Paragraph('6. Measurement notes',styles['Heading1']),Paragraph('CPU timings are single-run measurements and vary by machine and filesystem. The PF benchmark uses a deterministic pseudo-random access sequence; its LRU/MRU ranking should not be generalized to all workloads. The bottom-up bulk loader is specialized to the assignment dataset and fixed-width 8-byte character key.',styles['BodyText'])]
doc=SimpleDocTemplate(str(OUT),pagesize=A4,rightMargin=16*mm,leftMargin=16*mm,topMargin=15*mm,bottomMargin=15*mm,title='DBMS Assignment 1 Report')
doc.build(story)
print(OUT)
